p=Path('easyeda_scripts'); p.mkdir(exist_ok=True)
base="""const all = await eda.sch_PrimitiveComponent.getAllPrimitiveId(undefined, true); const found = {}; for (const id of all) { const c = await eda.sch_PrimitiveComponent.get(id); if (c) found[c.getState_Designator()] = c; } const search = async (term) => { const xs = await eda.lib_Device.search('', undefined, undefined, undefined, 200, 1); const hit = (xs || []).find(x => JSON.stringify(x).toLowerCase().includes(term.toLowerCase())); if (!hit) throw new Error('Library device not found: '+term); return hit; }; const place = async (ref, term, x, y, value, mpn, addPcb=true) => { if (found[ref]) return {ref, reused:true}; const d=await search(term); const c=await eda.sch_PrimitiveComponent.create(d,x,y,undefined,0,false,true,addPcb); if (!c) throw new Error('Create failed: '+ref); await eda.sch_PrimitiveComponent.modify(c,{designator:ref,name:value,manufacturer:mpn,otherProperty:{MPN:mpn,Value:value}}); found[ref]=c; return {ref,reused:false,id:c.getState_PrimitiveId()}; }; const result=[];"""
sections={
'00_API_preflight.js':"""const project = await eda.dmt_Project.getCurrentProjectInfo(); const sch = await eda.dmt_Schematic.getCurrentSchematicInfo(); const xs = await eda.lib_Device.search('', undefined, undefined, undefined, 100, 1); if (!project || !sch) throw new Error('No active project or schematic'); const r = (xs||[]).find(x=>JSON.stringify(x).toLowerCase().includes('resistor')); if (!r) throw new Error('No library resistor found'); const t=await eda.sch_PrimitiveComponent.create(r,1800,1800,undefined,0,false,false,false); if (!t) throw new Error('Preflight create failed'); const pins=await t.getAllPins(); const report={project,schematic:sch,libraryDeviceCount:(xs||[]).length,testDesignator:t.getState_Designator(),pinCount:(pins||[]).length,pins:(pins||[]).map(x=>({number:x.getState_PinNumber(),name:x.getState_PinName(),x:x.getState_X(),y:x.getState_Y()}))}; await eda.sch_PrimitiveComponent.delete([t.getState_PrimitiveId()]); return report;""",
'01_power_inputs_charging.js': base+"""result.push(await place('U2','BQ24074',2600,1800,'1S charger/power path','BQ24074RGT')); result.push(await place('U6','TPS2660',1800,1800,'6V input eFuse','TPS26600RGET')); result.push(await place('J1','USB',1200,1600,'USB-C 5V sink','USB4105-GF-A')); result.push(await place('J4','PH',1200,2300,'Battery','S2B-PH-SM4-TB')); return {section:'power_inputs',result,note:'Run only after 00 preflight; exact library symbols must match MPN drawings.'};""",
'02_regulators_power.js': base+"""result.push(await place('U3','TPS62161',4200,1800,'3V3 buck','TPS62161DSG')); result.push(await place('L1','2.2uH',3900,1800,'2.2uH shielded inductor','datasheet-selected')); result.push(await place('Q1','TPS22919',4700,2200,'Dock load switch','TPS22919DCK')); return {section:'regulators',result};""",
'03_esp32_core.js': base+"""result.push(await place('U1','ESP32-S3-WROOM-1-N16R8',6500,2200,'ESP32-S3-WROOM-1-N16R8','ESP32-S3-WROOM-1-N16R8')); return {section:'esp32_core',result,note:'Use manufacturer symbol/pin mapping; do not accept approximate library match.'};""",
'04_external_sensors_audio.js': base+"""result.push(await place('U7','SHT45',8500,1600,'External T/RH','SHT45')); result.push(await place('MIC1','ICS-43434',8500,2300,'External I2S microphone','ICS-43434')); result.push(await place('U-IMU','ICM-42688',8500,3000,'Optional IMU','ICM-42688-P')); return {section:'external_sensors_audio',result};""",
'05_storage_rf_expansion.js': base+"""result.push(await place('J-SD','microSD',10500,1800,'SPI storage DNP','microSD socket',false)); result.push(await place('J-RF','header',10500,2800,'RF expansion','SPI/UART 3V3 GND',false)); return {section:'storage_rf',result,note:'DNP options; assign exact footprints before layout.'};""",
'06_docking_interface.js': base+"""result.push(await place('U4','TCA9546A',12500,1800,'I2C branch switch','TCA9546APWR')); result.push(await place('D5','TPD4E05',12500,2600,'Dock ESD','TPD4E05U06')); result.push(await place('J3','Mill-Max',12500,3400,'12-contact pogo interface','0906-0-15-20-75-14-11-0 x12',false)); return {section:'dock',result,pinout:'GND,GND,GND,VDOCK,VDOCK,+3V3_FPC,SDA,SCL,BCLK,WS,SD,PRESENT_ID'};""",
'07_universal_sensor_fpc.js': base+"""result.push(await place('J2','FH34SRJ-12S',14500,1800,'12-position FPC ZIF','FH34SRJ-12S-0.5SH(50)',false)); result.push(await place('U8','SHT45',14500,2500,'Internal T/RH','SHT45',false)); result.push(await place('MIC2','ICS-43434',14500,3200,'Internal microphone','ICS-43434',false)); result.push(await place('U9','ICM-42688',14500,3900,'Internal IMU','ICM-42688-P',false)); result.push(await place('U10','SGP40',14500,4600,'VOC DNP','SGP40',false)); return {section:'fpc',result,board:'Board B / two-layer polyimide FPC'};""",
'08_status_debug_test.js': base+"""result.push(await place('D2','LTST-C193KRKT',17000,1600,'Red fault/charge','LTST-C193KRKT-5A')); result.push(await place('D3','LTST-C193KGKT',17000,2200,'Green ready','LTST-C193KGKT-5A')); result.push(await place('D4','LTST-C193KBKT',17000,2800,'Blue logging/link','LTST-C193KBKT-5A')); return {section:'status_test',result,testPoints:['VBUS_USB','VIN_EXT_PROTECTED','VBAT','VSYS','+3V3','VDOCK','GND','I2C_MAIN','I2S','UART0']};""",
'09_final_verification.js':"""const ids=await eda.sch_PrimitiveComponent.getAllPrimitiveId(undefined,true); const rows=[]; for (const id of ids) { const c=await eda.sch_PrimitiveComponent.get(id); if(c){ const pins=await c.getAllPins(); rows.push({id,ref:c.getState_Designator(),name:c.getState_Name(),pinCount:(pins||[]).length,pins:(pins||[]).map(p=>({number:p.getState_PinNumber(),name:p.getState_PinName(),x:p.getState_X(),y:p.getState_Y()}))}); }} const wires=await eda.sch_PrimitiveWire.getAllPrimitiveId(undefined); const sch=await eda.dmt_Schematic.getCurrentSchematicInfo(); return {schematic:sch,components:rows,wires:wires.length,erc:'EasyEDA API reference exposes no ERC invocation in this skill version; run native EasyEDA ERC manually and record errors.'};"""
}
for fn,body in sections.items(): (p/fn).write_text(body+'\n',encoding='utf8')
